class Node:
    def __init__(self, value):
        self.value = value
        self.left = None
        self.right = None

class Bst:
    def __init__(self, root):
        self.root = root

    def insert(self, value):
        current = self.root
        while True:
            if value < current.value:
                if current.left is None:
                    current.left = Node(value)
                    break
                else:
                    current = current.left
            else:
                if current.right is None:
                    current.right = Node(value)
                    break
                else:
                    current = current.right

class BstHeightSolution(Bst):
    def height(self, node):
        if node is None:
            return 0
        return 1 + max(self.height(node.left), self.height(node.right))

def main_solution(insertion_order):
    if not insertion_order:
        return 0
    root = Node(insertion_order[0])
    bst = BstHeightSolution(root)
    for val in insertion_order[1:]:
        bst.insert(val)
    return bst.height(bst.root)

