class TopDownMergeSort:
    """Merge sort algorithm that returns a sorted copy of elements."""

    @classmethod
    def sort(cls, elements):
        if len(elements) == 1:
            return elements
        mid = len(elements) // 2
        left_half = cls.sort(elements[:mid])
        right_half = cls.sort(elements[mid:])
        return cls._merge(left_half, right_half)

    @staticmethod
    def _merge(left, right):
        n = len(left)
        m = len(right)
        result = [None] * (n + m)
        i = j = k = 0
        while i < n and j < m:
            if left[i] <= right[j]:
                result[k] = left[i]
                i += 1
            else:
                result[k] = right[j]
                j += 1
            k += 1

        while i < n:
            result[k] = left[i]
            i += 1
            k += 1
        while j < m:
            result[k] = right[j]
            j += 1
            k += 1

        return result


