import re

ACCEPTED_ISBN10_FORMAT = r'^\d{9}[0-9X]$'
ISBN10_DIGIT_GROUPS = r'(\d{2})(\d{3})(\d{4})([0-9X])'
ISBN10_FORMAT = r'\g<1>-\g<2>-\g<3>-\g<4>'

def main_solution(isbn):
    if not isinstance(isbn, str):
        return {'error': 'Invalid ISBN-10 type.'}

    if not re.match(ACCEPTED_ISBN10_FORMAT, isbn):
