        coefficient = 10 - index
        checksum += coefficient * digit

    if checksum % 11 != 0:
        return {'error': 'Invalid ISBN-10 value.'}

    match = re.match(ISBN10_DIGIT_GROUPS, isbn)
    if not match:
        return {'error': 'Invalid ISBN-10 structure.'}

    formatted_isbn = match.expand(ISBN10_FORMAT)
    return {'result': formatted_isbn}

