import collections

class TreeNode:
    def __init__(self, val=0, left=None, right=None):
        self.val = val
        self.left = left
        self.right = right

class Solution:
    def findDuplicateSubtrees(self, root):
        count = collections.Counter()
        ans = []
        def collect(node):
            if not node:
                return '#'
            tree_repr = "{},{},{}".format(node.val, collect(node.left), collect(node.right))
            count[tree_repr] += 1
            if count[tree_repr] == 2:
                ans.append(node)
            return tree_repr

        collect(root)
        return ans

def build_tree(serial):
    if not serial:
        return None
    nodes = serial.split(',')
    def build(it):
        val = next(it)
        if val == '#':
            return None
        node = TreeNode(int(val))
        node.left = build(it)
        node.right = build(it)
        return node
    return build(iter(nodes))

def serialize_tree(node):
