class Node:
    def __init__(self, char='*', complete=False):
        self.char = char
        self.d = {letter: None for letter in string.ascii_lowercase}
        self.complete = complete

def insert_helper(node: Node, word: str):
    if len(word) == 0:
        if node is not None:
            node.complete = True
        return

    if node.d[word[0]] is None:
