    fields = ["byr", "iyr", "eyr", "hgt", "hcl", "ecl", "pid"]
    validPassportP1 = 0
    validPassportP2 = 0
    validFieldsP1 = 0
    validFieldsP2 = 0

    for row in passport_data:
        # Part 1 processing
        if len(row) == 0 or validFieldsP1 == 7:
            validFieldsP1 = 0
        for part in re.split(" ", row):
            if len(part) >= 3 and part[:3] in fields:
                validFieldsP1 += 1
        if validFieldsP1 == 7:
            validPassportP1 += 1

        # Part 2 processing
        if row == "" or validFieldsP2 == 7:
            validFieldsP2 = 0
        for part in row.split(" "):
