            elif key == "iyr":
                if 2010 <= int(value) <= 2020:
                    validFieldsP2 += 1
            elif key == "eyr":
                if 2020 <= int(value) <= 2030:
                    validFieldsP2 += 1
            elif key == "hgt":
                if value.endswith("in"):
                    h = int(value[:-2])
                    if 59 <= h <= 76:
                        validFieldsP2 += 1
                elif value.endswith("cm"):
                    h = int(value[:-2])
                    if 150 <= h <= 193:
                        validFieldsP2 += 1
            elif key == "hcl":
                if len(value) == 7 and re.match(r'^#(?:[0-9a-fA-F]{3}){1,2}$', value):
                    validFieldsP2 += 1
            elif key == "ecl":
                if value in ["amb", "blu", "brn", "gry", "grn", "hzl", "oth"]:
                    validFieldsP2 += 1
            elif key == "pid":
                if len(value) == 9 and value.isdigit():
                    validFieldsP2 += 1
        if validFieldsP2 == 7:
            validPassportP2 += 1

    return {"part1": validPassportP1, "part2": validPassportP2}

