def main_solution(array, method):
    def insertion(arr):
        for i in range(len(arr)):
            while i - 1 >= 0:
                if arr[i] < arr[i - 1]:
                    arr[i], arr[i - 1] = arr[i - 1], arr[i]
                    i -= 1
                else:
                    break
        return arr

    def selection(arr):
        for i in range(len(arr)):
            min_ix = i
            for j in range(i, len(arr)):
                if arr[j] < arr[min_ix]:
                    min_ix = j
            arr[i], arr[min_ix] = arr[min_ix], arr[i]
        return arr

    def mergesort(arr):
        def merge_sorted(array1, array2):
            l1 = len(array1)
            l2 = len(array2)
            new_array = [0] * (l1 + l2)
            ix1 = 0
            ix2 = 0
            while ix1 < l1 and ix2 < l2:
                if array1[ix1] <= array2[ix2]:
                    new_array[ix1 + ix2] = array1[ix1]
                    ix1 += 1
                else:
                    new_array[ix1 + ix2] = array2[ix2]
                    ix2 += 1
            if ix1 < l1:
                new_array[ix1 + ix2:] = array1[ix1:]
            else:
                new_array[ix1 + ix2:] = array2[ix2:]
            return new_array
        if len(arr) <= 1:
            return arr
        return merge_sorted(mergesort(arr[:len(arr)//2]), mergesort(arr[len(arr)//2:]))

    if method == 'insertion':
        return insertion(array.copy())
    elif method == 'selection':
        return selection(array.copy())
    elif method == 'merge':
        return mergesort(array.copy())
    else:
        raise ValueError("Invalid method")

