        for i in range(N):
            # Check same column
            if chess[i][col]:
                return False
            # Check diagonal down-right
            if row + i < N and col + i < N:
                if chess[row + i][col + i]:
                    return False
            # Check diagonal up-left
            if 0 <= row - i and 0 <= col - i:
                if chess[row - i][col - i]:
                    return False
            # Check anti-diagonal
            if (row + col - N) < i and i < N:
                k = row + col - i
                if 0 <= k < N and chess[i][k]:
