            edge2 = Edge(v, u, bw)
            res1 = Edge(v, u, 0)
            res2 = Edge(u, v, 0)
            edge1.residual, res1.residual = res1, edge1
            edge2.residual, res2.residual = res2, edge2
            graph[u][v] = edge1
            graph[v][u] = edge2
    return solve(graph, s, t)

