from collections import deque

class TreeNode:
    def __init__(self, x):
        self.val = x
        self.left = None
        self.right = None

def list_to_tree(lst):
    if not lst:
        return None
    root = TreeNode(lst[0])
    queue = deque([root])
    i = 1
    while queue and i < len(lst):
        current = queue.popleft()
        if i < len(lst) and lst[i] is not None:
            current.left = TreeNode(lst[i])
            queue.append(current.left)
        i += 1
        if i < len(lst) and lst[i] is not None:
            current.right = TreeNode(lst[i])
            queue.append(current.right)
        i += 1
    return root

def tree_to_list(root):
    if not root:
        return []
    result = []
    queue = deque([root])
    while queue:
        node = queue.popleft()
        if node is None:
            result.append(None)
        else:
            result.append(node.val)
            queue.append(node.left)
            queue.append(node.right)
    while result and result[-1] is None:
        result.pop()
    return result

class Solution:
    def subtreeWithAllDeepest2(self, root: TreeNode) -> TreeNode:
        if not root: return None

        depth_dt = {}
        def dfs(nd, depth):
            depth_dt[nd] = depth
            if nd.left:
                dfs(nd.left, depth+1)
            if nd.right:
                dfs(nd.right, depth+1)
        dfs(root, 1)
        maximum_depth = max(depth_dt.values())

        def helper(nd):
            if not nd or depth_dt[nd] == maximum_depth:
                return nd
            L = helper(nd.left)
            R = helper(nd.right)
            if L and R: return nd
            return L if L else R
        return helper(root)

def main_solution(input_tree):
    root = list_to_tree(input_tree)
    sol = Solution()
    result_node = sol.subtreeWithAllDeepest2(root)
    output_tree = tree_to_list(result_node)
    return output_tree

