def generate_subsets(s):
    res = [""]
    for c in s:
        temp = []
        for subset in res:
            temp.append(subset + c)
        res += temp
    return res

def main_solution(words, puzzles):
    word_masks = collections.Counter()
    for word in words:
        mask = 0
        for c in word:
            mask |= 1 << (ord(c) - ord('a'))
        word_masks[mask] += 1

    result = []
    for puzzle in puzzles:
        first_char = puzzle[0]
        rest_chars = puzzle[1:]
        subsets = generate_subsets(rest_chars)
        total = 0
        for subset in subsets:
            mask = 1 << (ord(first_char) - ord('a'))
            for c in subset:
                mask |= 1 << (ord(c) - ord('a'))
            total += word_masks.get(mask, 0)
        result.append(total)
    return result

