Given a list of key-value pairs, determine the inorder and postorder traversal sequences of the binary search tree that results from inserting these pairs in the order they appear in the list. What are the traversal sequences produced by the binary search tree constructed with the provided key-value pairs?

The input and output requirements are as follows:

Input:
  `items` (list of lists): A list of key-value pairs where each element is a 2-element list `[key, value]`. Keys are unique integers.

Output:
  `return` (dict): A dictionary with two keys:
    - `inorder` (str): A string representing the inorder traversal of the binary search tree in the format "Inorder:key1->key2->...->keyN".
    - `postorder` (str): A string representing the postorder traversal of the binary search tree in the format "Postorder:key1->key2->...->keyN".

Given the following input:

{'items': [[5, 5], [42, 42], [48, 48], [26, 26], [47, 47]]}

Can you predict the output without writing any code? Return only your final answer in the following JSON format: {"output": <your output>}, where <your output> should strictly match the the output requirement as specified.

Tip: Here is a reference code snippet for this question. You can refer to this code to guide your reasoning but not copy spans of code directly.

class CalcKeyVal:
    def __init__(self, key, value):
        self.key = key
        self.value = value


class BinaryTreeNode:
    def __init__(self, data, left=None, right=None, parent=None):
        self.data = data
        self.left = left
        self.right = right
        self.parent = parent

    @property
    def key(self):
        return self.data.key

    @property
    def value(self):
        return self.data.value

    def put(self, data):
        if self.data.key == data.key:
            self.data = data
        elif self.data.key > data.key:
            if self.left is None:
                self.left = BinaryTreeNode(data)
                self.left.parent = self
            else:
                self.left.put(data)
        else:
            if self.right is None:
                self.right = BinaryTreeNode(data)
                self.right.parent = self
            else:
                self.right.put(data)

    def inorder_node(self, root):
        if root.left:
            for node in root.left.inorder_node(root.left):
                yield node
        yield root
        if root.right:
            for node in root.right.inorder_node(root.right):
                yield node

    def postorder_node(self, root):
        if root.left:
            for node in root.left.postorder_node(root.left):
                yield node
        if root.right:
            for node in root.right.postorder_node(root.right):
                yield node
        yield root


class BinarySearchTreeDict:
    def __init__(self):
        self.root = None
        self.size = 0

    def __setitem__(self, key, value):
        data = CalcKeyVal(key, value)
        if self.root is None:
            self.root = BinaryTreeNode(data)
        else:
            self.root.put(data)
        self.size += 1

    def main_solution(self, items):
        for key, value in items:
            self[key] = value
        inorder = "Inorder:" + "->".join(str(node.key) for node in self.root.inorder_node(self.root))
        postorder = "Postorder:" + "->".join(str(node.key) for node in self.root.postorder_node(self.root))
        return {"inorder": inorder, "postorder": postorder}


def main_solution(items):
    bst = BinarySearchTreeDict()
    return bst.main_solution(items)

