def main_solution(difficulty_level, answer, guesses):
    allowed_attempts = 10 if difficulty_level == 'easy' else 5
    remaining_attempts = allowed_attempts
    for i, guess in enumerate(guesses):
        if guess == answer:
            return {'result': 'success', 'attempts_used': i + 1}
        remaining_attempts -= 1
        if remaining_attempts == 0:
            return {'result': 'failure', 'correct_answer': answer}
    return {'result': 'failure', 'correct_answer': answer}

