def main_solution(first_num: str, second_num: str, operator: str) -> dict:
    """
    Performs arithmetic operations on two numbers based on the provided operator.
    Handles invalid inputs and division by zero errors gracefully.

    Args:
        first_num (str): First number as a string (must be convertible to integer)
        second_num (str): Second number as a string (must be convertible to integer)
        operator (str): Arithmetic operator (+, -, *, /)

    Returns:
        dict: Contains either 'result' with the operation outcome or 'error' with the error message
    """
    try:
        num1 = int(first_num)
        num2 = int(second_num)
    except ValueError:
        return {"error": "Invalid input: please enter valid integers."}

    if operator not in ['+', '-', '*', '/']:
        return {"error": "Invalid operator. Please use +, -, *, or /."}

    try:
        if operator == '+':
            result = num1 + num2
        elif operator == '-':
            result = num1 - num2
        elif operator == '*':
            result = num1 * num2
        else:  # operator == '/'
            result = num1 / num2
    except ZeroDivisionError:
        return {"error": "Division by zero is not allowed."}

    return {"result": result}

