class ListNode:
    def __init__(self, x):
        self.val = x
        self.next = None

def getIntersectionNode(headA: ListNode, headB: ListNode) -> ListNode:
    cur_a = headA
    cur_b = headB
    len_a = 0
    len_b = 0
    while cur_a:
        len_a += 1
        cur_a = cur_a.next

    while cur_b:
        len_b += 1
        cur_b = cur_b.next

    cur_a = headA
    cur_b = headB

    if len_a > len_b:
        for i in range(len_a - len_b):
            cur_a = cur_a.next

    elif len_b > len_a:
        for i in range(len_b - len_a):
            cur_b = cur_b.next

    while cur_a:
        if cur_a == cur_b:
            return cur_a
        cur_a = cur_a.next
        cur_b = cur_b.next

    return None

def create_linked_list(values):
    if not values:
        return None
    head = ListNode(values[0])
    current = head
    for val in values[1:]:
        current.next = ListNode(val)
        current = current.next
    return head

def main_solution(listA, listB, common):
    common_head = create_linked_list(common)

    a_unique = create_linked_list(listA)
    if a_unique:
        current = a_unique
        while current.next:
            current = current.next
        current.next = common_head
    headA = a_unique if a_unique else common_head

    b_unique = create_linked_list(listB)
    if b_unique:
        current = b_unique
        while current.next:
            current = current.next
        current.next = common_head
    headB = b_unique if b_unique else common_head

    intersection_node = getIntersectionNode(headA, headB)
    return intersection_node.val if intersection_node else None

