import math

def merge(src, result, start, inc):
    """Merge arc[start:start+inc] and src[start+inc:start+2*inc] into result"""
    end1 = start + inc
    end2 = min(start + 2 * inc, len(src))

    x, y, z = start, start + inc, start
    while x < end1 and y < end2:
        if src[x] < src[y]:
            result[z] = src[x]
            x += 1
        else:
            result[z] = src[y]
            y += 1
        z += 1
    if x < end1:
        result[z:end2] = src[x:end1]
    elif y < end2:
        result[z:end2] = src[y:end2]

def mergeSort(arr):
    """Sort the elements of arr using the merge-sort algorithm"""
    n = len(arr)
    logn = math.ceil(math.log(n, 2)) if n > 1 else 1
    src, dest = arr[:], [None] * n

    for i in (2**k for k in range(logn)):
        for j in range(0, n, 2 * i):
            merge(src, dest, j, i)
        src, dest = dest, src

    return src if n > 0 else []

def main_solution(arr):
    # Create a copy to avoid modifying the original input
    arr_copy = list(arr)
    sorted_arr = mergeSort(arr_copy)
    return sorted_arr

