def main_solution(arr):
    def merge(arrA, arrB):
        elements = len(arrA) + len(arrB)
        merged_arr = [0] * elements
        i = 0
        j = 0
        k = 0
        for _ in range(elements):
            if j >= len(arrA):
                merged_arr[i] = arrB[k]
                k += 1
            elif k >= len(arrB):
                merged_arr[i] = arrA[j]
                j += 1
            elif arrA[j] < arrB[k]:
                merged_arr[i] = arrA[j]
                j += 1
            else:
                merged_arr[i] = arrB[k]
                k += 1
            i += 1
        return merged_arr

    def merge_sort(arr):
        if len(arr) > 1:
            mid = len(arr) // 2
            lhs = merge_sort(arr[:mid])
            rhs = merge_sort(arr[mid:])
            arr = merge(lhs, rhs)
        return arr

    return merge_sort(arr)

def main_solution(word, guesses):
    previous_guesses = []
    correct_guesses = []
    found = []
    incorrect_count = 0

    for guess in guesses:
        if guess in previous_guesses:
            continue
        previous_guesses.append(guess)

        if guess in word:
            if guess not in correct_guesses:
                correct_guesses.append(guess)
                found.extend([guess] * word.count(guess))
        else:
            incorrect_count += 1

        if len(found) == len(word):
            break

    completed = len(found) == len(word)
    return {
        "completed": completed,
        "incorrect_guesses": incorrect_count,
        "correct_letters": correct_guesses
    }

# Definition for singly-linked list
class ListNode(object):
    def __init__(self, x):
        self.val = x
        self.next = None

def create_linked_list(values):
    if not values:
        return None
    head = ListNode(values[0])
    current = head
    for val in values[1:]:
        current.next = ListNode(val)
        current = current.next
    return head

def linked_list_to_list(head):
    result = []
    current = head
    while current:
        result.append(current.val)
        current = current.next
    return result

class Solution(object):
    def reverseKGroup(self, head, k):
        if not head or k <= 1:
            return head
        fake = last = ListNode(0)
        fake.next = head
        while head:
            if not self.checkEnough(head, k): 
                break
            first, tail = self.reverse(head, k)
            last.next = first
            last = tail
            head = last.next
        return fake.next

    def reverse(self, head, k):
        tail = head
        first = head
        second = first.next
        while k > 1:
            third = second.next
            second.next = first
            first = second
            second = third
            k -= 1
        tail.next = second
        return first, tail

    def checkEnough(self, head, k):
        while head and k > 0:
            k -= 1
            head = head.next
        return k == 0

def main_solution(values, k):
    head = create_linked_list(values)
    if not head:
        return values
    sol = Solution()
    new_head = sol.reverseKGroup(head, k)
    return linked_list_to_list(new_head)

