    """Compress a string by replacing consecutive repeated characters with the character followed by its count.
    Returns the original string if compression doesn't reduce its length."""
    if len(s) < 2:
        return s

    prev_char = s[0]
    count = 1
    compressed = ""

    for i in range(1, len(s)):
        if s[i] == prev_char:
            count += 1
        else:
            compressed += prev_char + str(count)
            prev_char = s[i]
            count = 1

