import collections
from typing import List

INF = 2147483647

class Solution:
    def wallsAndGates(self, rooms: List[List[int]]) -> None:
        if not rooms:
            return
        R, C = len(rooms), len(rooms[0])
        dq = collections.deque()
        for i in range(R):
            for j in range(C):
                if rooms[i][j] == 0:
                    dq.append((i, j))
        dis = 1
        while dq:
            l = len(dq)
            for _ in range(l):
                i, j = dq.popleft()
                for x, y in [(0, 1), (0, -1), (1, 0), (-1, 0)]:
                    nx, ny = i + x, j + y
                    if 0 <= nx < R and 0 <= ny < C and rooms[nx][ny] == INF:
                        rooms[nx][ny] = dis
                        dq.append((nx, ny))
            dis += 1

def main_solution(rooms: List[List[int]]) -> List[List[int]]:
    solution = Solution()
    solution.wallsAndGates(rooms)
    return rooms

