from collections import deque

def main_solution(matrix):
    Z = len(matrix)
    if Z == 0:
        return 0 if all(cell == 1 for layer in matrix for row in layer for cell in row) else -1
    N = len(matrix[0])
    if N == 0:
        return 0
    M = len(matrix[0][0])
    if M == 0:
        return 0

    queue = deque()
    weight = deque()

    for z in range(Z):
        for y in range(N):
            for x in range(M):
                if matrix[z][y][x] == 1:
                    queue.append([z, y, x])
                    weight.append(2)

    dz = [0, 0, 0, 0, 1, -1]
    dx = [1, -1, 0, 0, 0, 0]
    dy = [0, 0, 1, -1, 0, 0]

