            zz = cur_z + dz[i]
            yy = cur_y + dy[i]
            xx = cur_x + dx[i]

            if 0 <= zz < Z and 0 <= yy < N and 0 <= xx < M:
                if matrix[zz][yy][xx] == 0:
                    matrix[zz][yy][xx] = w
                    queue.append([zz, yy, xx])
                    weight.append(w + 1)

    def breakPoint(matrix):
        for h in matrix:
            for row in h:
